'use strict'

/**
 * Focused Apple Watch band-variant vision pass.
 *
 * The buyer-facing vocabulary is deliberately NOT generated by AI. Vision has
 * one job: partition the listing photos into distinct physical bands and choose
 * a representative image for each group. Deterministic code then names those
 * groups "Band 1", "Band 2", ... in first-photo order.
 *
 * This separation matters because a band can be multicolour, patterned, enamel,
 * mixed-metal, or visually close to another option. Colour names are therefore
 * neither complete nor stable identifiers. Numbered options remain short and
 * unambiguous as long as Etsy shows the linked variation image beside each one.
 */

const productTypes = require('./product-types')
const { config } = require('./config')

const MAX_VARIANTS = 24
const DEFAULT_CONFIDENCE_FLOOR = 60

const BAND_VARIANT_SCHEMA = {
	name: 'band_style_variations',
	strict: true,
	schema: {
		type: 'object',
		additionalProperties: false,
		properties: {
			variants: {
				type: 'array',
				items: {
					type: 'object',
					additionalProperties: false,
					properties: {
						// Internal evidence only; never becomes Etsy option text.
						visual_signature: { type: 'string' },
						image_indexes: { type: 'array', items: { type: 'integer' } },
						primary_image_index: { type: 'integer' },
						confidence: { type: 'integer' },
						evidence: { type: 'string' },
					},
					required: [
						'visual_signature',
						'image_indexes',
						'primary_image_index',
						'confidence',
						'evidence',
					],
				},
			},
			overall_confidence: { type: 'integer' },
			reasoning: { type: 'string' },
		},
		required: ['variants', 'overall_confidence', 'reasoning'],
	},
}

function compactText(value, maxLength) {
	return String(value == null ? '' : value)
		.replace(/[\u0000-\u001f\u007f]/g, ' ')
		.replace(/[<>]/g, '')
		.replace(/\s+/g, ' ')
		.trim()
		.slice(0, maxLength)
		.trim()
}

function clampConfidence(value) {
	const n = Number(value)
	return Number.isFinite(n) ? Math.max(0, Math.min(100, Math.round(n))) : 0
}

function validImageIndexes(raw, imageCount) {
	const out = []
	for (const value of Array.isArray(raw) ? raw : []) {
		const n = Number(value)
		if (!Number.isInteger(n) || n < 1 || n > imageCount || out.includes(n)) continue
		out.push(n)
	}
	return out
}

function signatureKey(value) {
	return compactText(value, 160)
		.toLocaleLowerCase('en-US')
		.replace(/[^\p{L}\p{N}]+/gu, ' ')
		.trim()
}

/**
 * Validate, deduplicate and order the provider response. The order is based on
 * where each physical option first appears in the gallery—not on a model's
 * arbitrary response order—so Band numbers are reproducible.
 */
function normaliseBandVariantAnalysis(input, imageCount) {
	const root = Array.isArray(input)
		? input.find((value) => value && typeof value === 'object' && !Array.isArray(value))
		: input
	const maxImage = Math.max(0, Number(imageCount) || 0)
	const bySignature = new Map()

	for (const raw of root && Array.isArray(root.variants) ? root.variants : []) {
		if (!raw || typeof raw !== 'object') continue
		const visualSignature = compactText(raw.visual_signature, 160)
		const key = signatureKey(visualSignature)
		if (!key || /^(?:unknown|unclear|same|band|watch band)$/.test(key)) continue

		const imageIndexes = validImageIndexes(raw.image_indexes, maxImage)
		const requestedPrimary = Number(raw.primary_image_index)
		if (
			Number.isInteger(requestedPrimary)
			&& requestedPrimary >= 1
			&& requestedPrimary <= maxImage
			&& !imageIndexes.includes(requestedPrimary)
		) {
			imageIndexes.unshift(requestedPrimary)
		}
		if (!imageIndexes.length) continue

		const candidate = {
			visualSignature,
			imageIndexes,
			primaryImageIndex: imageIndexes.includes(requestedPrimary) ? requestedPrimary : imageIndexes[0],
			confidence: clampConfidence(raw.confidence),
			evidence: compactText(raw.evidence, 280),
		}
		const prior = bySignature.get(key)
		if (!prior) {
			bySignature.set(key, candidate)
			continue
		}

		// The same physical signature was returned twice: combine its photo set and
		// keep the strongest representative verdict.
		prior.imageIndexes = [...new Set([...prior.imageIndexes, ...candidate.imageIndexes])].sort((a, b) => a - b)
		if (candidate.confidence > prior.confidence) {
			prior.confidence = candidate.confidence
			prior.primaryImageIndex = candidate.primaryImageIndex
			prior.evidence = candidate.evidence
			prior.visualSignature = candidate.visualSignature
		}
	}

	const variants = [...bySignature.values()]
		.sort((a, b) =>
			Math.min(...a.imageIndexes) - Math.min(...b.imageIndexes)
			|| a.primaryImageIndex - b.primaryImageIndex
			|| b.confidence - a.confidence
		)
		.slice(0, MAX_VARIANTS)

	return {
		variants,
		overallConfidence: clampConfidence(root && root.overall_confidence),
		reasoning: compactText(root && root.reasoning, 500),
	}
}

function bestImageRank(variant, imageAnalysis) {
	const quality = new Map(
		(Array.isArray(imageAnalysis) ? imageAnalysis : []).map((entry) => [
			Number(entry.index),
			Number(entry.thumbnail_quality) || 0,
		])
	)
	return variant.imageIndexes.slice().sort((a, b) => {
		if (a === variant.primaryImageIndex) return -1
		if (b === variant.primaryImageIndex) return 1
		return (quality.get(b) || 0) - (quality.get(a) || 0) || a - b
	})[0] || null
}

/** Canonical buyer-facing value for the Nth detected group. */
function bandLabel(index) {
	return `Band ${Number(index) + 1}`
}

/**
 * Re-number a reviewed custom-style list after add/remove/reorder. IDs and image
 * links remain stable; only the intentionally positional buyer labels change.
 */
function numberBandStyles(styles) {
	return (Array.isArray(styles) ? styles : []).slice(0, MAX_VARIANTS).map((style, index) => ({
		...style,
		id: style && style.id ? String(style.id) : `band-${index + 1}`,
		label: bandLabel(index),
	}))
}

/**
 * Materialise confident visual groups into the existing custom-style inventory
 * contract. The model never supplies labels: numbering is deterministic after
 * low-confidence groups are removed, so there can be no gaps such as Band 1,
 * Band 3.
 */
function materialiseBandVariants(analysis, { price, imageAnalysis, confidenceFloor = DEFAULT_CONFIDENCE_FLOOR } = {}) {
	const amount = Number(price)
	if (!Number.isFinite(amount) || amount <= 0) return []
	const accepted = (analysis && Array.isArray(analysis.variants) ? analysis.variants : [])
		.filter((variant) => variant && clampConfidence(variant.confidence) >= confidenceFloor)
		.slice(0, MAX_VARIANTS)

	return accepted.map((variant, index) => ({
		id: `band-${index + 1}`,
		label: bandLabel(index),
		price: Math.round(amount * 100) / 100,
		imageRank: bestImageRank(variant, imageAnalysis),
	}))
}

function buildPrompt(imageCount) {
	return `You are auditing ${imageCount} product photos for ONE Etsy Apple Watch band listing. Partition the photos into DISTINCT PURCHASABLE PHYSICAL BAND OPTIONS.

This is visual inventory grouping, not colour naming and not marketing copy. A single option may contain MANY colours, patterns, enamel panels, charms, mixed metals or other details. Treat its complete visual design as one identity.

GROUP AS THE SAME OPTION:
  • alternate angles, close-ups, clasp views, lifestyle shots and packaging of the same physical band;
  • the same design shown on different Apple Watch case sizes;
  • lighting, reflections, camera white balance or background changes;
  • a comparison image and a solo image when they clearly show the same band.

CREATE SEPARATE OPTIONS ONLY WHEN:
  • buyers are visibly being offered different physical bands—different link/enamel pattern, colour arrangement, artwork, material, charm arrangement or metal treatment;
  • the difference belongs to the band itself, not to the watch body, screen or props.

IGNORE COMPLETELY:
  • Apple Watch body colour, screen, watch face and on-screen graphics;
  • skin, clothing, props, backgrounds, shadows and reflections;
  • printed size charts, measurements and packaging swatches unless a matching physical band is shown;
  • camera angle, clasp position and watch case size.

For each group return:
  • "visual_signature": a concise INTERNAL description specific enough to distinguish this physical band from the other groups. It may describe multiple colours. This will never be shown to buyers;
  • "image_indexes": every image number that shows that same option;
  • "primary_image_index": the clearest image buyers should see when selecting it—prefer a dedicated full-band photo over a comparison collage;
  • "confidence": 0-100 that the group is a distinct purchasable option;
  • "evidence": one short literal explanation of why these photos belong together and differ from the other groups.

Do NOT create or suggest buyer-facing names; deterministic code will label accepted groups "Band 1", "Band 2", and so on. Do not split one multicolour band into one option per colour. Return one group when all photos show the same physical band. Return an empty variants array when distinct options cannot be determined safely.`
}

async function analyzeBandVariants(client, { images, callStructured, encodeImage, productType }) {
	const pt = productTypes.getProductType(productType)
	if (pt.visionStyle !== 'band_variant' || !Array.isArray(images) || !images.length) return null

	const content = [{ type: 'text', text: buildPrompt(images.length) }]
	for (let i = 0; i < images.length; i++) {
		content.push({ type: 'text', text: `\nIMAGE ${i + 1}:` })
		content.push(await encodeImage(images[i].path, images[i].mime, 'high'))
	}
	const messages = [
		{
			role: 'system',
			content: 'You are a conservative e-commerce product-variant grouping specialist. Group photos by distinct physical Apple Watch band design, including multicolour designs, and never invent buyer-facing names. Return only valid JSON matching the schema.',
		},
		{ role: 'user', content },
	]
	const parsed = await callStructured(client, {
		messages,
		schema: BAND_VARIANT_SCHEMA,
		maxTokens: config.openai.visionMaxTokens
			? Math.min(6000, config.openai.visionMaxTokens)
			: 0,
		model: config.openai.visionModel,
		reasoningEffort: config.openai.reasoningEffort,
		temperature: 0,
	})
	return normaliseBandVariantAnalysis(parsed, images.length)
}

module.exports = {
	analyzeBandVariants,
	normaliseBandVariantAnalysis,
	materialiseBandVariants,
	numberBandStyles,
	bandLabel,
	BAND_VARIANT_SCHEMA,
	MAX_VARIANTS,
	DEFAULT_CONFIDENCE_FLOOR,
}
